float clouds_cumulus_optical_depth(
    vec3 ray_origin,
    vec3 ray_dir,
    float dither,
    uint step_count,
    uint original_steps
) {
    const float step_growth = 2.0;

    float step_length = 0.1 * clouds_cumulus_thickness / float(step_count); // m

    // Geometric step distribution sums to (2^N-1). Preserve the original
    // secondary-ray extent when lowering N instead of shortening optical depth.
    if (step_count != original_steps) {
        step_length *= (float(step_count) / float(original_steps)) *
            (exp2(float(original_steps)) - 1.0) / (exp2(float(step_count)) - 1.0);
    }
    vec3 ray_pos = ray_origin;
    vec4 ray_step = vec4(ray_dir, 1.0) * step_length;

    float optical_depth = 0.0;

    for (uint i = 0u; i < step_count; ++i, ray_pos += ray_step.xyz) {
        ray_step *= step_growth;
        optical_depth +=
            clouds_cumulus_density(ray_pos + ray_step.xyz * dither) *
            ray_step.w;
    }

    return optical_depth;
}

